311	            Self::Introspection => "introspection",
312	            Self::Layout => "layout",
313	            Self::DataLoading => "data-loading",
314	            Self::Math => "math",
315	            Self::Model => "model",
316	            Self::Symbols => "symbols",
317	            Self::Text => "text",
318	            Self::Visualize => "visualize",
319	            Self::Pdf => "pdf",
